"+\" en lo que quieras pedir.<\/div>\n    <div class=\"cp-coupon\"><label for=\"cp-coupon-in\" id=\"cp-coupon-lbl\">¿Tenés un cupón?<\/label><div class=\"cp-coupon-row\"><input id=\"cp-coupon-in\" maxlength=\"24\" autocomplete=\"off\" placeholder=\"CÓDIGO\"><button type=\"button\" id=\"cp-coupon-ok\">Aplicar<\/button><\/div><div id=\"cp-coupon-msg\" role=\"status\"><\/div><\/div>\n    <div class=\"cp-total-row\">\n      <span>Total estimado<\/span>\n      <span id=\"cp-total-val\">$ 0<\/span>\n    <\/div>\n    <div class=\"cp-note\">Los ítems marcados \"a coordinar\" se confirman por WhatsApp.<\/div>\n    <div class=\"cp-buttons\">\n      <button class=\"cp-btn clear\" id=\"btn-clear\" type=\"button\">Vaciar<\/button>\n      <button class=\"cp-btn send\" id=\"btn-send\" type=\"button\">Enviar por WhatsApp<\/button>\n    <\/div>\n    <button class=\"cp-close\" id=\"btn-close\" type=\"button\">Seguir viendo el menú<\/button>\n  <\/div>\n<\/div>\n\n<\script>\n(function(){\n  var cart = {}; // id -> {name, price(number|null), qty}\n\n  var cartBar = document.getElementById('cart-bar');\n  var cbCount = document.getElementById('cb-count');\n  var cbTotal = document.getElementById('cb-total');\n  var overlay = document.getElementById('cart-overlay');\n  var itemsEl = document.getElementById('cart-items');\n  var emptyEl = document.getElementById('cart-empty');\n  var totalValEl = document.getElementById('cp-total-val');\n  var toTopBtn = document.getElementById('to-top');\n  var saleFab = document.getElementById('sale-fab');\n\n  function fmt(n){\n    return '$ ' + n.toLocaleString('es-AR');\n  }\n\n  function updateElementUI(el, qty){\n    var qv = el.querySelector('.qty-val');\n    if(qv) qv.textContent = qty;\n    if(qty > 0){ el.classList.add('in-cart'); } else { el.classList.remove('in-cart'); }\n  }\n\n  function refreshBar(){\n    var count = 0, total = 0, hasUnpriced = false;\n    Object.keys(cart).forEach(function(id){\n      var it = cart[id];\n      count += it.qty;\n      if(it.price !== null){ total += it.price * it.qty; } else { hasUnpriced = true; }\n    });\n    if(count > 0){\n      cartBar.style.display = 'flex';\n    } else {\n      cartBar.style.display = 'none';\n    }\n    cbCount.textContent = count;\n    cbTotal.textContent = fmt(total) + (hasUnpriced ? ' +' : '');\n    toTopBtn.classList.toggle('lift', count > 0);\n    saleFab.classList.toggle('lift', count > 0);\n  }\n\n  // ---- Botón flotante \"volver arriba\" ----\n  window.addEventListener('scroll', function(){\n    toTopBtn.classList.toggle('show', window.scrollY > 480);\n  });\n  toTopBtn.addEventListener('click', function(){\n    window.scrollTo({ top: 0, behavior: 'smooth' });\n  });\n\n  function renderPanel(){\n    var ids = Object.keys(cart);\n    itemsEl.innerHTML = '';\n    if(ids.length === 0){\n      emptyEl.style.display = 'block';\n    } else {\n      emptyEl.style.display = 'none';\n      var total = 0;\n      ids.forEach(function(id){\n        var it = cart[id];\n        var lineTxt;\n        if(it.price !== null){\n          var line = it.price * it.qty;\n          total += line;\n          lineTxt = fmt(line);\n        } else {\n          lineTxt = (window.rvT ? rvT('A coordinar') : 'A coordinar');\n        }\n        var row = document.createElement('div');\n        row.className = 'cp-item';\n        row.setAttribute('data-pid', String(id));\n        row.innerHTML = '<div class=\"cp-name\">' + String(it.name == null ? '' : it.name).replace(/[&<>\"']/g, function(ch){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'})[ch]; }) + '<\/div>' +\n                         '<div class=\"cp-qty\">x' + it.qty + '<\/div>' +\n                         '<div class=\"cp-line\">' + lineTxt + '<\/div>';\n        itemsEl.appendChild(row);\n      });\n      totalValEl.textContent = fmt(total);\n    }\n    window.RAVE_CART_TOTAL = total; if(window.RAVE_COUPON_RENDER) window.RAVE_COUPON_RENDER(total);\n  }\n\n  function changeQty(el, delta){\n    var id = el.dataset.id;\n    var name = el.dataset.name;\n    var priceAttr = el.dataset.price;\n    var price = (priceAttr === '' || priceAttr === undefined) ? null : parseInt(priceAttr, 10);\n\n    if(!cart[id]) cart[id] = { name: name, price: price, qty: 0 };\n    cart[id].qty += delta;\n    if(cart[id].qty <= 0){ delete cart[id]; updateElementUI(el, 0); }\n    else { updateElementUI(el, cart[id].qty); }\n\n    refreshBar();\n  }\n\n  /* Los botones + y - no se enganchan uno por uno: el catalogo ahora se arma\n     con datos y se puede volver a dibujar (cuando el panel cambia un precio o\n     agrega un producto), asi que se escucha por delegacion. */\n  document.addEventListener('click', function(e){\n    var btn = e.target.closest ? e.target.closest('.sheet .qty-btn') : null;\n    if(!btn) return;\n    var el = btn.closest('[data-id]');\n    if(!el) return;\n    e.stopPropagation();\n    changeQty(el, btn.classList.contains('plus') ? 1 : -1);\n  });\n\n  /* ===== Filtro por categorías + buscador + modal de detalle ===== */\n  var catChips = document.querySelectorAll('.cat-chip');\n  var searchInput = document.getElementById('search-input');\n  var searchEmpty = document.getElementById('search-empty');\n  var activeCat = 'all';\n\n  // ---- Contador de productos por categoría (chips \"Promos 19\", etc.) ----\n  function countItemsFor(cat){\n    var vistos = [];\n    document.querySelectorAll('[data-cat=\"' + cat + '\"]').forEach(function(el){\n      var items = el.hasAttribute('data-id') ? [el] : el.querySelectorAll('[data-id]');\n      Array.prototype.forEach.call(items, function(it){\n        var id = it.getAttribute('data-id');\n        if(vistos.indexOf(id) === -1) vistos.push(id);\n      });\n    });\n    return vistos.length;\n  }\n  function initCounts(){\n    var cats = window.RAVE_CATS || ['promo', 'vino', 'tabaco'];\n    var total = 0;\n    cats.forEach(function(cat){\n      var n = countItemsFor(cat);\n      total += n;\n      var el = document.getElementById('count-' + cat);\n      if(el) el.textContent = n;\n    });\n    var totalEl = document.getElementById('count-all');\n    if(totalEl) totalEl.textContent = total;\n  }\n  initCounts();\n\n  function applyFilters(){\n    var term = (searchInput.value || '').trim().toLowerCase();\n    var anyVisible = false;\n\n    document.querySelectorAll('.section[data-cat], .featured[data-cat]').forEach(function(container){\n      var cat = container.getAttribute('data-cat');\n      var catMatch = (activeCat === 'all' || activeCat === cat);\n\n      if(container.classList.contains('featured')){\n        var name = (container.dataset.name || '').toLowerCase();\n        var visible = catMatch && (term === '' || name.indexOf(term) !== -1);\n        container.style.display = visible ? '' : 'none';\n        if(visible) anyVisible = true;\n        return;\n      }\n\n      // .section: filtrar tarjetas/filas internas por nombre, y ocultar la\n      // seccion entera si no queda ninguna visible.\n      var items = container.querySelectorAll('[data-id]');\n      var sectionHasVisible = false;\n      items.forEach(function(item){\n        var iname = (item.dataset.name || '').toLowerCase();\n        var match = term === '' || iname.indexOf(term) !== -1;\n        item.style.display = match ? '' : 'none';\n        if(match) sectionHasVisible = true;\n      });\n      var showSection = catMatch && sectionHasVisible;\n      container.style.display = showSection ? '' : 'none';\n      if(showSection) anyVisible = true;\n    });\n\n    searchEmpty.style.display = (!anyVisible && term !== '') ? 'block' : 'none';\n  }\n\n  document.addEventListener('click', function(e){\n    var chip = e.target.closest ? e.target.closest('.cat-chip') : null;\n    if(!chip) return;\n    document.querySelectorAll('.cat-chip').forEach(function(c){ c.classList.remove('active'); });\n    chip.classList.add('active');\n    activeCat = chip.getAttribute('data-cat');\n    applyFilters();\n  });\n  searchInput.addEventListener('input', applyFilters);\n\n  /* el render del catalogo llama a esto despues de redibujar */\n  window.RAVE_MENU_REFRESH = function(){ initCounts(); applyFilters(); };\n\n  // ---- Modal de detalle de producto ----\n  var pmOverlay = document.getElementById('product-modal-overlay');\n  var pmImg = document.getElementById('pm-img');\n  var pmName = document.getElementById('pm-name');\n  var pmSub = document.getElementById('pm-sub');\n  var pmPrice = document.getElementById('pm-price');\n  var pmQtyVal = document.getElementById('pm-qtyval');\n  var pmPlus = document.getElementById('pm-plus');\n  var pmMinus = document.getElementById('pm-minus');\n  var currentModalEl = null;\n\n  function fmtMaybe(priceAttr){\n    if(priceAttr === '' || priceAttr === undefined) return (window.rvT ? rvT('A coordinar por WhatsApp') : 'A coordinar por WhatsApp');\n    return fmt(parseInt(priceAttr, 10));\n  }\n\n  function syncModalQty(){\n    if(!currentModalEl) return;\n    var qv = currentModalEl.querySelector('.qty-val');\n    pmQtyVal.textContent = qv ? qv.textContent : '0';\n  }\n\n  function openModal(el){\n    currentModalEl = el;\n    var img = el.querySelector('img');\n    var subEl = el.querySelector('.c-sub, .desc, .row-name');\n    pmImg.style.display = img ? '' : 'none';\n    if(img) pmImg.src = img.src;\n    pmName.textContent = el.dataset.name || '';\n    pmSub.textContent = (subEl && subEl !== el.querySelector('.row-name')) ? subEl.textContent : '';\n    pmPrice.textContent = fmtMaybe(el.dataset.price);\n    syncModalQty();\n    pmOverlay.style.display = 'flex';\n  }\n  function closeModal(){\n    pmOverlay.style.display = 'none';\n    currentModalEl = null;\n  }\n\n  document.addEventListener('click', function(e){\n    if(!e.target.closest) return;\n    if(e.target.closest('.qty-btn')) return;\n    var el = e.target.closest('.sheet .card, .sheet .row, .sheet .featured');\n    if(el) openModal(el);\n  });\n  pmPlus.addEventListener('click', function(){\n    if(!currentModalEl) return;\n    var realPlus = currentModalEl.querySelector('.qty-btn.plus');\n    if(realPlus) realPlus.click();\n    syncModalQty();\n  });\n  pmMinus.addEventListener('click', function(){\n    if(!currentModalEl) return;\n    var realMinus = currentModalEl.querySelector('.qty-btn.minus');\n    if(realMinus) realMinus.click();\n    syncModalQty();\n  });\n  document.getElementById('pm-add').addEventListener('click', function(){\n    if(!currentModalEl) return;\n    var realPlus = currentModalEl.querySelector('.qty-btn.plus');\n    if(realPlus) realPlus.click();\n    syncModalQty();\n  });\n  document.getElementById('pm-close').addEventListener('click', closeModal);\n  document.getElementById('pm-close-x').addEventListener('click', closeModal);\n  pmOverlay.addEventListener('click', function(e){ if(e.target === pmOverlay) closeModal(); });\n\n  cartBar.addEventListener('click', function(){\n    renderPanel();\n    overlay.style.display = 'flex';\n  });\n  document.getElementById('btn-close').addEventListener('click', function(){\n    overlay.style.display = 'none';\n  });\n  overlay.addEventListener('click', function(e){\n    if(e.target === overlay) overlay.style.display = 'none';\n  });\n\n  document.getElementById('btn-clear').addEventListener('click', function(){\n    Object.keys(cart).forEach(function(id){\n      var el = document.querySelector('[data-id=\"' + id + '\"]');\n      if(el) updateElementUI(el, 0);\n    });\n    cart = {};\n    refreshBar();\n    renderPanel();\n  });\n\n  document.getElementById('btn-send').addEventListener('click', function(){\n    var ids = Object.keys(cart);\n    if(ids.length === 0) return;\n    var lines = ['Hola RAVE! Quiero hacer este pedido:'];\n    var total = 0;\n    ids.forEach(function(id){\n      var it = cart[id];\n      if(it.price !== null){\n        var line = it.price * it.qty;\n        total += line;\n        lines.push('- ' + it.qty + 'x ' + it.name + ' — ' + fmt(line));\n      } else {\n        lines.push('- ' + it.qty + 'x ' + it.name + ' — a coordinar');\n      }\n    });\n    lines.push('');\n    lines.push('Subtotal estimado: ' + fmt(total));\n    if(window.RAVE_COUPON_LINES) window.RAVE_COUPON_LINES(lines, total);\n    if(window.RAVE_SHIP_LINES) window.RAVE_SHIP_LINES(lines, total);\n    lines.push('');\n    lines.push('Espero su confirmación, gracias!');\n    var msg = lines.join('\\n');\n    try{ if(window.RAVE_ORDER_LOG) window.RAVE_ORDER_LOG(ids.map(function(i){ return { id:i, name:cart[i].name, price:cart[i].price, qty:cart[i].qty }; }), total); }catch(e){}\n    var url = 'https://wa.me/' + (window.RAVE_WA || '5493874574892') + '?text=' + encodeURIComponent(msg);\n    window.open(url, '_blank');\n  });\n})();\n\n/* ===== Club RAVE: alta de clientes + panel de administrador =====\n   NOTA PARA REUTILIZAR ESTE ARCHIVO COMO PLANTILLA CON OTRO NEGOCIO:\n   cambiar ADMIN_PASSWORD y WA_NUMBER más abajo, y el texto de la cláusula\n   legal si el negocio no es RAVE.\n\n   Seguridad y cumplimiento (Ley 25.326 de Protección de Datos Personales):\n   - Minimización de datos: el formulario solo pide nombre, WhatsApp y\n     cumpleaños — lo mínimo necesario para sorteos/ofertas/saludos.\n   - Sanitización centralizada: toda entrada del cliente pasa por\n     sanitizeInput() antes de guardarse o mostrarse, para evitar\n     inyección de HTML/script (XSS).\n   - Ofuscación de almacenamiento: los datos en localStorage NO se\n     guardan como texto plano, se pasan por obfuscate()/deobfuscate().\n     Esto es una ofuscación razonable, NO un cifrado real: en un archivo\n     estático sin servidor no hay forma de esconder una clave secreta\n     verdadera, así que alguien que revise el código fuente podría\n     revertirla. Para cifrado real y control de acceso genuino, el\n     paso siguiente (cuando este servicio se venda formalmente) es un\n     backend propio con login y token de autorización, como el panel\n     completo de Cannabismática.\n   - El acceso al panel de administrador es un freno liviano (doble\n     clic + contraseña en este mismo archivo), no autenticación real.\n   - Los datos se guardan únicamente en este dispositivo. Por eso además\n     se manda un respaldo por WhatsApp al número del negocio en cada alta.\n   - Derechos ARCO: el botón \"Ejercé tus derechos ARCO\" del formulario\n     le permite a cualquier persona pedir acceso, corrección o borrado\n     de sus propios datos, enviando el pedido directo al WhatsApp del\n     negocio.\n   - Los errores nunca se muestran técnicos al usuario final: si algo\n     falla (por ejemplo, el navegador bloquea localStorage), se ve un\n     mensaje genérico, nunca el detalle interno.\n*/\n(function(){\n  var STORAGE_KEY = 'rave_club_clientes';\n  var WA_NUMBER = window.RAVE_WA || '5493874574892';\n\n  // ==== Cartera de clientes centralizada (Google Sheet) ====\n  // Completar estos dos valores cuando esté publicado el Web App de Apps Script\n  // (ver instrucciones aparte). Mientras SHEET_WEBHOOK_URL esté vacío, el alta\n  // sigue funcionando igual que antes (guardado local + WhatsApp de respaldo),\n  // simplemente no manda nada a la planilla todavía.\n  var SHEET_WEBHOOK_URL = '';\n  var SHEET_TOKEN = '';\n\n  // ---- Sanitización centralizada (XSS) ----\n  function sanitizeInput(str){\n    return String(str == null ? '' : str)\n      .replace(/[\\r\\n\\t]/g, ' ')\n      .trim()\n      .replace(/[&<>'\"]/g, function(tag){\n        return ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', \"'\":'&#39;', '\"':'&quot;' })[tag] || tag;\n      });\n  }\n  var escapeHTML = sanitizeInput; // alias: mismo uso, nombre historico\n\n  // ---- Ofuscación de lo que se guarda en localStorage (ver nota arriba) ----\n  function b64EncodeUnicode(str){\n    return btoa(encodeURIComponent(str).replace(/%([0-9A-F]{2})/g, function(_, hex){\n      return String.fromCharCode(parseInt(hex, 16));\n    }));\n  }\n  function b64DecodeUnicode(str){\n    return decodeURIComponent(Array.prototype.map.call(atob(str), function(c){\n      return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);\n    }).join(''));\n  }\n  function obfuscate(str){\n    var shifted = str.split('').map(function(ch){ return String.fromCharCode(ch.charCodeAt(0) + 7); }).join('');\n    return b64EncodeUnicode(shifted);\n  }\n  function deobfuscate(str){\n    try{\n      var shifted = b64DecodeUnicode(str);\n      return shifted.split('').map(function(ch){ return String.fromCharCode(ch.charCodeAt(0) - 7); }).join('');\n    }catch(e){ return null; }\n  }\n\n  function getClientes(){\n    try{\n      var raw = localStorage.getItem(STORAGE_KEY);\n      if(!raw) return [];\n      var json = deobfuscate(raw);\n      return json ? (JSON.parse(json) || []) : [];\n    }catch(e){ return []; }\n  }\n  function saveClientes(list){\n    try{\n      localStorage.setItem(STORAGE_KEY, obfuscate(JSON.stringify(list)));\n      return true;\n    }catch(e){ return false; } // localStorage bloqueado/lleno: fallamos en silencio, sin exponer detalle técnico\n  }\n\n  // ---- Formulario de alta ----\n  var form = document.getElementById('club-form');\n  var fNombre = document.getElementById('club-nombre');\n  var fWhats = document.getElementById('club-whatsapp');\n  var fCumple = document.getElementById('club-cumple');\n  var fConsent = document.getElementById('club-consent');\n  var okMsg = document.getElementById('club-ok');\n  var errMsg = document.getElementById('club-error');\n\n  function setInvalid(fieldId, invalid){\n    var el = document.getElementById(fieldId);\n    if(el) el.classList.toggle('invalid', invalid);\n  }\n\n  form.addEventListener('submit', function(e){\n    e.preventDefault();\n    errMsg.style.display = 'none';\n    var nombre = sanitizeInput(fNombre.value);\n    var whats = sanitizeInput(fWhats.value);\n    var cumple = fCumple.value;\n\n    var nombreOk = nombre.length >= 3 && /[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+\\s+[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]/.test(nombre);\n    var whatsDigits = whats.replace(/\\D/g, '');\n    var whatsOk = whatsDigits.length >= 8;\n    var cumpleOk = !!cumple;\n    var dniEl = document.getElementById('club-dni'); var dniDigits = dniEl ? dniEl.value.replace(/\\D/g,'') : '';\n    var dniOk = !dniEl || !dniEl.value.trim() || (dniDigits.length >= 7 && dniDigits.length <= 8);\n\n    setInvalid('field-nombre', !nombreOk);\n    setInvalid('field-whatsapp', !whatsOk);\n    setInvalid('field-cumple', !cumpleOk);\n    setInvalid('field-dni', !dniOk);\n\n    if(!nombreOk || !whatsOk || !cumpleOk || !dniOk || !fConsent.checked) return;\n\n    var API = null; try{ API = window.parent.RAVE_API; }catch(e){}\n    var comm = !!(document.getElementById('club-comm') && document.getElementById('club-comm').checked);\n    var r0 = API ? API.clubJoin({ nombre:nombre, whatsapp:whatsDigits, cumple:cumple, comm:comm, dni:dniDigits }) : { ok:false };\n    Promise.resolve(r0).then(function(r){\n    var e2 = document.getElementById('club-error2');\n    if(!r || !r.ok){\n      if(e2){ e2.textContent = (r && r.msg) || ''; e2.style.display = (r && r.msg) ? 'block' : 'none'; }\n      if(!(r && r.msg)) errMsg.style.display = 'block';\n      return;\n    }\n    if(e2) e2.style.display = 'none';\n    try{ if(r.cardId) localStorage.setItem('rave.card', r.cardId); }catch(e){}\n    if(window.RAVE_CARD_REFRESH) window.RAVE_CARD_REFRESH();\n    okMsg.style.display = 'block';\n    form.reset();\n    setInvalid('field-nombre', false);\n    setInvalid('field-whatsapp', false);\n    setInvalid('field-cumple', false);\n    setInvalid('field-dni', false);\n    try{ var lbk=document.getElementById('loyalty-block'); if(lbk && lbk.scrollIntoView) lbk.scrollIntoView({ behavior:(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches)?'auto':'smooth', block:'start' }); }catch(e){}\n    setTimeout(function(){ okMsg.style.display = 'none'; }, 5000);\n    }).catch(function(){ errMsg.style.display = 'block'; });\n  });\n\n  // ---- Derechos ARCO (acceso, rectificación, cancelación, oposición) ----\n  document.getElementById('arco-btn').addEventListener('click', function(){\n    var msg = 'Quiero ejercer mis derechos ARCO (acceso, rectificacion, cancelacion u oposicion) sobre los datos que dejé en el Club RAVE.';\n    window.open('https://wa.me/' + WA_NUMBER + '?text=' + encodeURIComponent(msg), '_blank');\n  });\n\n\n  // El panel privado ahora lo maneja el Sistema RAVE (ver más abajo):\n  // el boton \"Acceso del equipo\" y el doble clic en el titulo llaman a\n  // window.RAVE_PANEL.abrir().\n})();\n<\/script>\n\n<\script>\n/* ===== Sistema RAVE · datos del comercio (antes del selector de idioma) ===== */\n(function(){\n  var API=null; try{ API=window.parent.RAVE_API; }catch(e){}\n  if(!API) return;\n  var S=API.site();\n  window.RAVE_WA=S.wa;\n  window.RAVE_ALCH={from:S.alcFrom,to:S.alcTo};\n  function esc(t){return String(t==null?'':t).replace(/[&<>\"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c];});}\n  function md(t){return esc(t).replace(/\\*\\*(.+?)\\*\\*/g,'<strong>$1<\/strong>');}\n  var $=function(s){return document.querySelector(s);};\n  var X=[]; // filas extra de traducción: [selector, inglés, modo]\n  function set(sel,es,en,mode){var e=$(sel); if(!e) return; if(!mode) e.innerHTML=es; if(en!=null) X.push([sel,en,mode]);}\n  // identidad\n  var bt=$('#brand-title'); if(bt) bt.textContent=S.title;\n  set('.brand-sub',md(S.sub.es),md(S.sub.en));\n  set('.pitch',md(S.pitch.es),md(S.pitch.en));\n  var pb=$('.promo-banner'); if(pb){ if(!S.promo.on) pb.style.display='none'; else set('.promo-banner .pt',md(S.promo.es),md(S.promo.en)); }\n  var an=$('#alc-notice'); if(an){ var hh=function(h){h=+h; return h>=24?'00:00':(h<10?'0':'')+h+':00';}; var f=hh(S.alcFrom), t=hh(S.alcTo); set('#alc-notice','Venta de bebidas alcohólicas habilitada de '+f+' a '+t+' (Salta). Volvé en ese horario.','Alcohol sales are allowed from '+f+' to '+t+' (Salta time). Please come back during those hours.'); }\n  // mapa, reseñas\n  var q=encodeURIComponent(S.mapQuery);\n  var fr=$('.map-embed iframe'); if(fr) fr.setAttribute('src','https://www.google.com/maps?q='+q+'&output=embed');\n  var mp=$('.map-panel .info-sub'); if(mp) mp.textContent=S.address;\n  var ml=$('.map-panel a.info-btn'); if(ml) ml.setAttribute('href',S.mapUrl);\n  var rl=$('.review-panel a.info-btn'); if(rl) rl.setAttribute('href',S.reviewUrl);\n  // Wi-Fi\n  var wp=$('.wifi-panel');\n  if(wp){ if(!S.wifi.on) wp.style.display='none'; else {\n    $('#wifi-ssid').textContent=S.wifi.ssid; $('#wifi-pass').textContent=S.wifi.pass;\n    var tg=wp.querySelector('.wifi-tag'); if(tg&&!S.wifi.example) tg.remove();\n  } }\n  // redes\n  var ul=$('#social-list');\n  if(ul){ var ic=S.icons||{}; ul.innerHTML=S.social.map(function(s){\n    var svg=ic[s.k]||'<svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"11\" fill=\"#555\"/><path d=\"M8 12h8M12 8v8\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\"/><\/svg>';\n    return '<li><a href=\"'+esc(s.url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">'+svg+'<span><b>'+esc(s.label)+'<\/b><small>'+esc(s.handle)+'<\/small><\/span><\/a><\/li>';}).join('');\n    var sp=$('.social-panel'); if(sp&&!S.social.length) sp.style.display='none'; }\n  // pie\n  var ft=$('footer'); if(ft){ for(var i=0;i<ft.childNodes.length;i++){var n=ft.childNodes[i]; if(n.nodeType===3&&n.nodeValue.trim()){ n.nodeValue=' '+S.footer.es+' '; X.push(['footer',' '+S.footer.en+' ','text']); break; } } }\n  // textos de los bloques nuevos (inglés)\n  [['#coupons-block h2','Coupons &amp; perks'],\n   ['#coupons-block .club-sub','Type the code in your order (cart) or show it at the counter. One benefit per purchase.'],\n   ['#loyalty-block h2','Your loyalty card'],\n   ['#loy-sub','Collect a stamp on every purchase and redeem them for Club RAVE rewards.'],\n   ['#loy-nocard-txt','Your card is created when you join the Club (form above). If you are already a member on another device, recover it with your WhatsApp and birthday.'],\n   ['label[for=\"loy-wa\"]','WhatsApp'],['label[for=\"loy-bd\"]','Birthday'],\n   ['#loy-ask','Ask for my card on WhatsApp'],['#loy-err','We could not find a card with those details.'],['#loy-recover','See my card'],\n   ['#plans-h','Memberships'],['#plans-sub','Permanent perks for members. Activated at the counter.'],\n   ['#legal-block h2','Legal information'],['#legal-sub','Everything you need to know about your purchase and your data.'],\n   ['#arrep-btn','↩️ Withdrawal button'],\n   ['#cp-coupon-lbl','Got a coupon?'],['#cp-coupon-ok','Apply'],\n   ['#club-comm-txt','I agree to receive promotions and coupons via WhatsApp (optional, you can unsubscribe at any time).']\n  ].forEach(function(r){X.push(r);});\n  window.RAVE_T_EXTRA=X;\n})();\n\n<\/script>\n<\script>\n/* ===== Idioma (ES/EN) + Compartir (Web Share API) + Wi-Fi ===== */\n(function(){\n  var lang = 'es';\n  window.RAVE_LANG = function(){ return lang; };\n  try { var sv = localStorage.getItem('rave_lang'); if(sv === 'en' || sv === 'es') lang = sv; } catch(e){}\n\n  // [selector, texto en inglés, modo]  modo: (vacío)=innerHTML | 'text'=primer nodo de texto | 'ph'=placeholder | 'aria'=aria-label\n  var T = [\n    ['.brand-sub','Grocery &amp; Liquor Store · Salta'],\n    ['.pitch','Buy your drinks —and much more— <strong>without leaving your car<\/strong>. Scan this QR and build your order: <strong>we confirm stock by WhatsApp<\/strong>, arrange payment and bring it to you during the afternoon.'],\n    ['.promo-banner .pt','Buy <strong>2 combos<\/strong> or <strong>3 wines<\/strong> and delivery is <strong>free<\/strong> within the downtown area and surroundings.'],\n    ['.price-note','🧾 All listed prices include taxes.'],\n    ['#search-input','Search product...','ph'],\n    ['#search-input','Search product','aria'],\n    ['#search-empty','No products found with that name.'],\n    ['.cat-chip[data-cat=\"all\"]','All','text'],\n    ['.cat-chip[data-cat=\"promo\"]','Deals','text'],\n    ['.cat-chip[data-cat=\"vino\"]','Wines','text'],\n    ['.cat-chip[data-cat=\"tabaco\"]','Tobacco','text'],\n    ['.section[data-cat=\"promo\"] h2','Drink Deals Menu'],\n    ['.section[data-cat=\"vino\"] h2','Wines'],\n    ['.section[data-cat=\"vino\"] .hint','By winery and variety'],\n    ['.section[data-cat=\"tabaco\"] h2','Cigarettes &amp; Tobacco'],\n    ['.club-block h2','Join Club RAVE'],\n    ['.club-sub','Be the first to hear about our deals, join members-only giveaways and get a surprise on your birthday.'],\n    ['label[for=\"club-nombre\"]','Full name'],\n    ['#club-nombre','e.g. John Smith','ph'],\n    ['#field-nombre .club-err','Enter your first and last name.'],\n    ['label[for=\"club-whatsapp\"]','WhatsApp'],\n    ['#club-whatsapp','e.g. 387 4567890','ph'],\n    ['#field-whatsapp .club-err','Enter a valid WhatsApp number (at least 8 digits).'],\n    ['label[for=\"club-cumple\"]','Birthday'],\n    ['label[for=\"club-dni\"]','ID number (optional)'],\n    ['#club-dni','e.g. 30123456','ph'],\n    ['#field-dni .club-err','The ID number must have 7 or 8 digits (or leave it empty).'],\n    ['#club-dni-hint','With your ID number we can add your stamps at the counter even if you do not have your phone at hand.'],\n    ['#field-cumple .club-err','Pick a valid date.'],\n    ['.club-consent span','I agree that RAVE stores this data solely to contact me about giveaways, offers and birthday greetings, in accordance with Argentine Law 25.326 on Personal Data Protection. My data is not shared with third parties.'],\n    ['#arco-btn','Want to access, correct or delete your data? Exercise your ARCO rights'],\n    ['.club-btn','Join Club RAVE'],\n    ['#club-ok','Done! You are now part of Club RAVE.'],\n    ['#club-error','We could not save your data on this device. Please try again in a moment.'],\n    ['.legal-details summary','Terms &amp; Privacy Policy'],\n    ['.map-panel h2','Where to find us'],\n    ['.map-panel .info-btn','📍 Get directions'],\n    ['.review-panel h2','How was your purchase?'],\n    ['.review-panel .info-sub','Your Google review helps more people find us. It takes one minute.'],\n    ['.review-panel .info-btn','⭐ Leave my Google review'],\n    ['.wifi-panel h2','📶 Wi-Fi for customers <span class=\"wifi-tag\">example<\/span>'],\n    ['.wifi-panel .info-sub','Connect while you wait for your order and share the network with whoever is with you.'],\n    ['.wifi-card div:nth-child(1)','Network: <b id=\"wifi-ssid\">RAVE-Clientes<\/b>'],\n    ['.wifi-card div:nth-child(2)','Password: <b id=\"wifi-pass\">rave-demo-2026<\/b>'],\n    ['#wifi-share','📤 Share Wi-Fi'],\n    ['#wifi-copy','📋 Copy password'],\n    ['.wifi-legal','Use subject to the store\\'s terms. RAVE is not responsible for how third parties use the network.'],\n    ['.social-panel h2','Follow us'],\n    ['.social-panel .info-sub','Deals, news and giveaways.'],\n    ['#share-menu-2','📤 Share the menu with your contacts'],\n    ['#share-menu .st-txt','Share'],\n    ['#share-menu','Share the menu','aria'],\n    ['footer','Grocery &amp; Liquor Store · Urquiza 1052 · Salta, Argentina','text'],\n    ['#team-access-btn','🔒 Team access'],\n    ['.dc-kicker','Developed by'],\n    ['.dev-credit .dc-tagline','“Your idea, in good hands.”'],\n    ['.dev-credit p:nth-of-type(2)','Custom software development: scalable, secure and results-oriented — web systems and PWA, multi-store ERP/POS, mobile apps, integrations and hardware, security and backup, support and maintenance.'],\n    ['.dc-btn.wa','💬 Only mobile (387) 4484132'],\n    ['.dc-btn.call','📞 Call (387) 4484132'],\n    ['.dc-fine','Developed by VINCULAR BUSINESS · Experience · Commitment · Innovation<br>Only mobile (387) 4484132 · vincularbusiness@gmail.com'],\n    ['#age-gate #ag-title','Age verification'],\n    ['#age-gate #ag-desc','This menu includes alcoholic beverages and tobacco. Are you over 18?'],\n    ['#ag-yes','I am over 18'],\n    ['#ag-no','I am under 18'],\n    ['#ag-deny','Sorry: you cannot access this content. Sale prohibited to persons under 18.'],\n    ['#age-gate .ag-legal','Sale prohibited to persons under 18. Drink responsibly.'],\n    ['#alc-legend','<span>🔞 Sale prohibited to persons under 18.<\/span><span>🥂 Drink responsibly.<\/span>'],\n    ['#alc-notice','Alcohol sales are allowed from 07:00 to 00:00 (Salta). Please come back during those hours.'],\n    ['.foot-legal','Sale prohibited to persons under 18. Drink responsibly.'],\n    ['#sale-fab .sf-txt','Your business?'],\n    ['#sale-fab','Have a business? Get this system for your store','aria'],\n    ['#cart-bar .cb-left',' item(s)','text2'],\n    ['#cart-panel h3','Your order'],\n    ['#cart-empty','You haven\\'t added anything yet. Tap \"+\" on what you want to order.'],\n    ['.cp-total-row span:first-child','Estimated total'],\n    ['.cp-note','Items marked \"to be arranged\" are confirmed via WhatsApp.'],\n    ['#btn-clear','Clear'],\n    ['#btn-send','Send via WhatsApp'],\n    ['#btn-close','Keep browsing the menu'],\n    ['#pm-add','Add to order'],\n    ['#pm-close','Keep browsing']\n  ].concat(window.RAVE_T_EXTRA || []);\n  var EXTRA = {\n    'A coordinar':'To be arranged',\n    'A coordinar por WhatsApp':'To be arranged via WhatsApp',\n    '¡Listo! Ya sos parte del Club RAVE.':'Done! You are now part of Club RAVE.'\n  };\n  var MSG = {\n    es:{ copied:'Clave copiada ✅', linkCopied:'Link copiado ✅', fail:'No se pudo compartir. Probá de nuevo.',\n         shareTitle:'Almacén y Licorería RAVE',\n         shareText:'Mirá el menú de Almacén y Licorería RAVE (Urquiza 1052, Salta): vinos, bebidas, cigarrillos y combos. Pedí por WhatsApp 👇',\n         wifiText:function(n,p){ return '📶 Wi-Fi de Almacén y Licorería RAVE\\nRed: '+n+'\\nClave: '+p; } },\n    en:{ copied:'Password copied ✅', linkCopied:'Link copied ✅', fail:'Could not share. Please try again.',\n         shareTitle:'Almacén y Licorería RAVE',\n         shareText:'Check out the menu of Almacén y Licorería RAVE (Urquiza 1052, Salta): wines, drinks, cigarettes and combos. Order via WhatsApp 👇',\n         wifiText:function(n,p){ return '📶 Wi-Fi at Almacén y Licorería RAVE\\nNetwork: '+n+'\\nPassword: '+p; } }\n  };\n\n  window.rvT = function(es){ return (lang === 'en' && EXTRA[es]) ? EXTRA[es] : es; };\n\n  function firstText(el){\n    for(var i=0;i<el.childNodes.length;i++){ var n=el.childNodes[i]; if(n.nodeType===3 && n.nodeValue.trim()) return n; }\n    return null;\n  }\n  function lastText(el){\n    for(var i=el.childNodes.length-1;i>=0;i--){ var n=el.childNodes[i]; if(n.nodeType===3 && n.nodeValue.trim()) return n; }\n    return null;\n  }\n  var captured = false;\n  function capture(){\n    if(captured) return; captured = true;\n    T.forEach(function(row){\n      var mode = row[2] || '';\n      document.querySelectorAll(row[0]).forEach(function(el){\n        var key = '__es_' + (mode || 'html');\n        if(el[key] !== undefined) return;\n        if(mode === 'ph') el[key] = el.getAttribute('placeholder');\n        else if(mode === 'aria') el[key] = el.getAttribute('aria-label');\n        else if(mode === 'text'){ var n=firstText(el); el[key] = n ? n.nodeValue : null; }\n        else if(mode === 'text2'){ var n2=lastText(el); el[key] = n2 ? n2.nodeValue : null; }\n        else el[key] = el.innerHTML;\n      });\n    });\n  }\n  function apply(){\n    capture();\n    var en = (lang === 'en');\n    T.forEach(function(row){\n      var mode = row[2] || '', key = '__es_' + (mode || 'html');\n      document.querySelectorAll(row[0]).forEach(function(el){\n        var val = en ? row[1] : el[key];\n        if(val === undefined || val === null) return;\n        if(mode === 'ph') el.setAttribute('placeholder', val);\n        else if(mode === 'aria') el.setAttribute('aria-label', val);\n        else if(mode === 'text'){ var n=firstText(el); if(n) n.nodeValue = en ? ' ' + row[1].replace(/&amp;/g,'&') + ' ' : val; }\n        else if(mode === 'text2'){ var n2=lastText(el); if(n2) n2.nodeValue = val; }\n        else el.innerHTML = val;\n      });\n    });\n    document.documentElement.lang = lang;\n    ['es','en'].forEach(function(l){\n      var b = document.getElementById('lang-' + l);\n      if(b) b.setAttribute('aria-pressed', l === lang ? 'true' : 'false');\n    });\n  }\n  function setLang(l){\n    lang = l; window.RAVE_LANGV = l;\n    try { localStorage.setItem('rave_lang', l); } catch(e){}\n    apply();\n  }\n\n  var toastEl = document.getElementById('rv-toast'), toastT;\n  function toast(t){\n    if(!toastEl) return;\n    toastEl.textContent = t; toastEl.classList.add('show');\n    clearTimeout(toastT); toastT = setTimeout(function(){ toastEl.classList.remove('show'); }, 2400);\n  }\n  function copyText(txt){\n    if(navigator.clipboard && navigator.clipboard.writeText){\n      return navigator.clipboard.writeText(txt);\n    }\n    return new Promise(function(res, rej){\n      try{\n        var ta = document.createElement('textarea'); ta.value = txt; ta.setAttribute('readonly','');\n        ta.style.position='fixed'; ta.style.opacity='0'; document.body.appendChild(ta); ta.select();\n        var ok = document.execCommand('copy'); document.body.removeChild(ta); ok ? res() : rej();\n      }catch(e){ rej(e); }\n    });\n  }\n  function shareUrl(){\n    var c = document.querySelector('link[rel=\"canonical\"]');\n    return c ? c.href : (location.origin + location.pathname);\n  }\n  // Compartir nativo; si el navegador no lo soporta, abre WhatsApp con el texto y el link\n  function doShare(title, text, url){\n    var data = { title: title, text: text };\n    if(url) data.url = url;\n    if(navigator.share){\n      return navigator.share(data).catch(function(e){ if(e && e.name === 'AbortError') return; fallback(); });\n    }\n    fallback();\n    function fallback(){\n      var msg = text + (url ? ' ' + url : '');\n      var w = window.open('https://wa.me/?text=' + encodeURIComponent(msg), '_blank', 'noopener');\n      if(!w){ copyText(msg).then(function(){ toast(MSG[lang].linkCopied); }, function(){ toast(MSG[lang].fail); }); }\n    }\n  }\n  function shareMenu(){ var m = MSG[lang]; doShare(m.shareTitle, m.shareText, shareUrl()); }\n  function wifiData(){\n    return { n: document.getElementById('wifi-ssid').textContent.trim(), p: document.getElementById('wifi-pass').textContent.trim() };\n  }\n\n  document.getElementById('lang-es').addEventListener('click', function(){ setLang('es'); });\n  document.getElementById('lang-en').addEventListener('click', function(){ setLang('en'); });\n  document.getElementById('share-menu').addEventListener('click', shareMenu);\n  document.getElementById('share-menu-2').addEventListener('click', shareMenu);\n  document.getElementById('wifi-share').addEventListener('click', function(){\n    var w = wifiData(); doShare(MSG[lang].shareTitle + ' · Wi-Fi', MSG[lang].wifiText(w.n, w.p), '');\n  });\n  document.getElementById('wifi-copy').addEventListener('click', function(){\n    copyText(wifiData().p).then(function(){ toast(MSG[lang].copied); }, function(){ toast(MSG[lang].fail); });\n  });\n\n  if(lang === 'en') apply();\n})();\n<\/script>\n<\script>\n/* ===== Age Gate (Ley 24.788) + restricción horaria opcional de alcohol ===== */\n(function(){\n  // Configurable: poner enabled:true para ocultar bebidas alcohólicas fuera del horario de venta (hora de Salta, 0-23).\n  // Salta: venta de alcohol permitida de 07:00 a 00:00 -> from:7, to:24. ACTIVADO. (decimal: 23.5 = 23:30)\n  var ALCOHOL_RESTRICTION = { enabled:true, from:(window.RAVE_ALCH?window.RAVE_ALCH.from:7), to:(window.RAVE_ALCH?window.RAVE_ALCH.to:24), tz:'America/Argentina/Salta',\n                              cats: window.RAVE_CATS_ALC || ['promo','vino'] };\n  var gate = document.getElementById('age-gate'), yes = document.getElementById('ag-yes'), no = document.getElementById('ag-no');\n  var sheet = document.querySelector('.sheet');\n  function ok(){ try{ return sessionStorage.getItem('rave_age18') === '1'; }catch(e){ return false; } }\n  function lock(on){\n    document.body.classList.toggle('age-locked', on);\n    if(sheet){ if(on) sheet.setAttribute('inert',''); else sheet.removeAttribute('inert'); sheet.setAttribute('aria-hidden', on?'true':'false'); }\n  }\n  function open(){ gate.classList.add('open'); lock(true); setTimeout(function(){ try{ yes.focus(); }catch(e){} }, 30); }\n  function close(){ gate.classList.remove('open'); lock(false); }\n  if(!ok()) open();\n  yes.addEventListener('click', function(){ try{ sessionStorage.setItem('rave_age18','1'); }catch(e){} close(); });\n  no.addEventListener('click', function(){ gate.classList.add('denied'); var d=document.getElementById('ag-deny'); if(d){ d.setAttribute('tabindex','-1'); d.focus(); } });\n  gate.addEventListener('keydown', function(e){ // focus trap\n    if(e.key !== 'Tab') return;\n    var f = [yes, no].filter(function(b){ return b.offsetParent !== null; });\n    if(!f.length){ e.preventDefault(); return; }\n    var i = f.indexOf(document.activeElement);\n    if(e.shiftKey && i <= 0){ e.preventDefault(); f[f.length-1].focus(); }\n    else if(!e.shiftKey && i === f.length-1){ e.preventDefault(); f[0].focus(); }\n  });\n\n  function nowDecimal(){\n    try{\n      var parts = new Intl.DateTimeFormat('en-GB',{timeZone:ALCOHOL_RESTRICTION.tz,hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());\n      var h=0,m=0; parts.forEach(function(x){ if(x.type==='hour') h=+x.value%24; if(x.type==='minute') m=+x.value; });\n      return h + m/60;\n    }catch(e){ var d=new Date(); return d.getHours()+d.getMinutes()/60; }\n  }\n  function applyHours(){\n    var R = ALCOHOL_RESTRICTION, closed = false;\n    if(R.enabled){ var n = nowDecimal(); closed = (R.from <= R.to) ? !(n >= R.from && n < R.to) : !(n >= R.from || n < R.to); }\n    document.body.classList.toggle('alc-closed', closed);\n    R.cats.forEach(function(c){\n      document.querySelectorAll('.section[data-cat=\"'+c+'\"], .cat-chip[data-cat=\"'+c+'\"]').forEach(function(el){ el.classList.toggle('alc-off', closed); });\n    });\n    if(closed){ var all=document.querySelector('.cat-chip[data-cat=\"all\"]'); var act=document.querySelector('.cat-chip.active'); if(act && act.classList.contains('alc-off') && all) all.click(); }\n  }\n  applyHours(); setInterval(applyHours, 60000);\n  window.RAVE_applyHours = applyHours; window.RAVE_ALC = ALCOHOL_RESTRICTION;\n})();\n<\/script>\n<\script>\n/* ===== Sistema RAVE · fidelización, cupones, legal, acceso del equipo ===== */\n(function(){\n  var API=null; try{ API=window.parent.RAVE_API; }catch(e){}\n  if(!API) return;\n  var $=function(s,r){return (r||document).querySelector(s);};\n  function esc(t){return String(t==null?'':t).replace(/[&<>\"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c];});}\n  function L(es,en){return (window.RAVE_LANG&&window.RAVE_LANG()==='en')?en:es;}\n  function money(p){return '$ '+Math.round(p).toLocaleString('es-AR');}\n  function toast(t){var el=$('#rv-toast'); if(!el) return; el.textContent=t; el.classList.add('show'); clearTimeout(toast._t); toast._t=setTimeout(function(){el.classList.remove('show');},2400);}\n  function copy(t){ if(navigator.clipboard&&navigator.clipboard.writeText) return navigator.clipboard.writeText(t); var ta=document.createElement('textarea'); ta.value=t; document.body.appendChild(ta); ta.select(); try{document.execCommand('copy');}catch(e){} ta.remove(); return Promise.resolve(); }\n\n  /* --- acceso del equipo: botón, doble clic en el título y 5 toques al logo --- */\n  function openPanel(){ try{ API.openPanel(); }catch(e){} }\n  var tb=$('#team-access-btn'); if(tb) tb.addEventListener('click',openPanel);\n  var bt=$('#brand-title'); if(bt) bt.addEventListener('dblclick',openPanel);\n  var lg=$('header .logo'), taps=[];\n  if(lg) lg.addEventListener('click',function(){var t=Date.now(); taps=taps.filter(function(x){return t-x<3000;}); taps.push(t); if(taps.length>=5){taps=[]; openPanel();}});\n  if(API.site().hideTeamBtn&&tb) tb.style.display='none';\n\n  /* --- cupones públicos --- */\n  function renderCoupons(){\n    var box=$('#coupons-block'), list=$('#coupons-list'); if(!box||!list) return;\n    var id=null; try{id=localStorage.getItem('rave.card');}catch(e){}\n    var cs=API.coupons(id);\n    box.hidden=!cs.length;\n    list.innerHTML=cs.map(function(c){\n      return '<div class=\"cp-card\"><div class=\"cc-txt\"><b class=\"cc-code\">'+esc(c.code)+'<\/b><div class=\"cc-d\">'+esc(c.desc)+'<\/div><div class=\"cc-s\">'+esc(c.cond)+'<\/div><\/div><button type=\"button\" data-copy=\"'+esc(c.code)+'\">'+L('Copiar','Copy')+'<\/button><\/div>';}).join('');\n  }\n  document.addEventListener('click',function(e){\n    var b=e.target.closest&&e.target.closest('[data-copy]'); if(!b) return;\n    var code=b.getAttribute('data-copy'); copy(code).then(function(){toast(L('Código copiado','Code copied')+': '+code);});\n    var inp=$('#cp-coupon-in'); if(inp) inp.value=code;\n  });\n\n  /* --- cupón dentro del pedido (se valida de nuevo en el mostrador) --- */\n  var applied=null;\n  function msg(t,cls){var m=$('#cp-coupon-msg'); if(!m) return; m.textContent=t||''; m.className=cls||'';}\n  function drawDisc(total){\n    var old=$('#cp-disc-row'); if(old) old.remove();\n    if(!applied) return;\n    var r=API.couponInfo(applied,total); \n    if(!r.ok){ msg(L(r.msg,r.msgEn||r.msg),'bad'); applied=null; return; }\n    msg(L('Cupón '+r.code+' aplicado: '+r.desc,'Coupon '+r.code+' applied: '+(r.descEn||r.desc)),'ok');\n    var row=document.createElement('div'); row.id='cp-disc-row'; row.className='cp-total-row disc';\n    row.innerHTML='<span>'+L('Total con cupón (estimado)','Total with coupon (estimate)')+'<\/span><span>'+money(r.total)+'<\/span>';\n    var tr=$('.cp-total-row'); tr.parentNode.insertBefore(row,tr.nextSibling);\n  }\n  window.RAVE_COUPON_RENDER=function(total){drawDisc(total);};\n  window.RAVE_COUPON_LINES=function(lines,total){\n    if(!applied) return; var r=API.couponInfo(applied,total); if(!r.ok) return;\n    lines.push('Cupón: '+r.code+' (se valida en el local) — total estimado con cupón: '+money(r.total));\n  };\n  window.RAVE_ORDER_LOG=function(items,total){ try{ API.orderRequest({items:items,total:total,coupon:applied||''}); }catch(e){} };\n  var ok=$('#cp-coupon-ok'), inp=$('#cp-coupon-in');\n  if(ok) ok.addEventListener('click',function(){\n    var code=(inp.value||'').trim().toUpperCase(); if(!code){msg('');applied=null;drawDisc(0);return;}\n    var tot=window.RAVE_CART_TOTAL||0; var r=API.couponInfo(code,tot);\n    if(!r.ok){applied=null;msg(L(r.msg,r.msgEn||r.msg),'bad');var o=$('#cp-disc-row');if(o)o.remove();return;}\n    applied=r.code; drawDisc(tot);\n  });\n\n  /* --- tarjeta de fidelización --- */\n  /* V26.19: tarjeta de EJEMPLO (como en todos los menús de Sistema VB): muestra cómo se ve la tarjeta, la meta y el premio antes de sumarse */\n  function renderSample(){\n    var box=$('#loy-sample'); if(!box) return; var s={}; try{s=API.site()||{};}catch(e){}\n    var cl=s.club||{}, g=Math.max(2,Math.min(30,+cl.goal||10)), n=Math.min(g-1,Math.max(1,Math.round(g*0.6))), rw=String(cl.reward||'');\n    var dots=''; for(var i=0;i<g;i++){ var on=i<n, pz=(i===g-1); dots+='<i class=\"'+(on?'on':'')+(pz&&!on?' loy-pz':'')+'\">'+(on?'★':(pz?'🎁':(i+1)))+'<\/i>'; }\n    box.innerHTML='<div class=\"loy-card loy-sample\"><span class=\"loy-ej\">'+L('EJEMPLO','SAMPLE')+'<\/span><h3>'+L('Así se ve tu tarjeta','This is how your card looks')+'<\/h3>'\n     +'<div class=\"loy-sub\">'+L('Un sello por cada compra','One stamp per purchase')+'<\/div>'\n     +'<div class=\"loy-stamps\" style=\"grid-template-columns:repeat('+Math.min(g,5)+',1fr)\">'+dots+'<\/div>'\n     +'<div class=\"loy-meta\"><span>'+n+' / '+g+' '+L('sellos','stamps')+'<\/span><span>'+L('Te faltan '+(g-n),(g-n)+' to go')+'<\/span><\/div>'\n     +(rw&&!/a definir/i.test(rw)?'<div class=\"loy-reward\">🎁 '+L('Con ','With ')+g+L(' sellos: ',' stamps: ')+esc(rw)+'<\/div>':'')\n     +'<\/div>';\n  }\n  var tick=null;\n  function cardId(){try{return localStorage.getItem('rave.card')||'';}catch(e){return '';}}\n  function stopTick(){clearInterval(tick);tick=null;}\n  function renderCard(){\n    var id=cardId(), c=id?API.card(id):null;\n    var no=$('#loy-nocard'), cd=$('#loy-card'); if(!no||!cd) return;\n    stopTick();\n    var rec=document.querySelector('.loy-rec'), canRec=!(API.canRecover&&!API.canRecover());\n    if(rec) rec.style.display=canRec?'':'none';\n    var nt=$('#loy-nocard-txt'); if(nt&&!canRec) nt.textContent=L('Tu tarjeta se crea al sumarte al Club (formulario de arriba) y queda guardada en este celular. Si ya eras socio y no la ves (cambiaste de celular o borraste los datos del navegador), pedila por WhatsApp: el negocio te manda el enlace de tu tarjeta y al abrirlo vuelve a quedar guardada.','Your card is created when you join the Club (form above) and is kept on this phone. If you were already a member and cannot see it (new phone or cleared browser data), ask for it on WhatsApp: the shop sends you your card link and opening it saves it again.');\n    var ask=$('#loy-ask'); if(ask){ ask.hidden=canRec; if(!canRec){ var sw=''; try{sw=API.site().wa||'';}catch(e){} sw=String(sw).replace(/\\D/g,'')||String(window.RAVE_WA||'').replace(/\\D/g,''); ask.onclick=function(){ window.open('https://wa.me/'+sw+'?text='+encodeURIComponent(L('Hola! Ya soy socio del Club pero no veo mi tarjeta en este celular. ¿Me mandan el enlace de mi tarjeta? Mi nombre es: ','Hi! I am already a Club member but I cannot see my card on this phone. Could you send me my card link? My name is: ')),'_blank','noopener'); }; } }\n    if(!c){ renderSample(); no.hidden=false; cd.hidden=true; if(id&&canRec){try{localStorage.removeItem('rave.card');}catch(e){}} renderPlans(null); return; }\n    no.hidden=true; cd.hidden=false;\n    var dots=''; for(var i=0;i<c.goal;i++) dots+='<i class=\"'+(i<c.stamps?'on':'')+'\">'+(i<c.stamps?'★':'')+'<\/i>';\n    var left=Math.max(0,c.goal-c.stamps);\n    cd.innerHTML='<div class=\"loy-card\"><h3>'+esc(c.name)+'<\/h3><div class=\"loy-sub\">'+(c.pending?L('Socio N° en trámite · el negocio la activa en unos segundos','Member # pending · the shop activates it in a few seconds'):L('Socio N° ','Member # ')+esc(c.num))+'<\/div>'\n     +'<div class=\"loy-stamps\" style=\"grid-template-columns:repeat('+Math.min(c.goal,5)+',1fr)\">'+dots+'<\/div>'\n     +'<div class=\"loy-meta\"><span>'+c.stamps+' / '+c.goal+' '+L('sellos','stamps')+'<\/span><span>'+(left?L('Te faltan '+left,left+' to go'):L('¡Tenés un premio!','You have a reward!'))+'<\/span><\/div>'\n     +(c.rewards?'<div class=\"loy-reward\">🎁 '+L('Premio disponible: ','Reward available: ')+esc(c.rewardText)+(c.rewards>1?' (x'+c.rewards+')':'')+'<\/div>':'')\n     +(c.member?'<div class=\"loy-member\">⭐ '+esc(c.member.name)+' · '+L('hasta ','until ')+esc(c.member.until)+(c.member.pct?' · '+c.member.pct+'% '+L('de descuento en el mostrador','off at the counter'):'')+'<\/div>':'')\n     +'<div id=\"loy-codebox\"><\/div>'\n     +'<button type=\"button\" class=\"loy-btn\" id=\"loy-show\">'+L('Mostrar mi código para sumar sello','Show my code to get a stamp')+'<\/button>'\n     +'<p class=\"loy-tip\">'+L('Tip: agregá esta página a la pantalla de inicio de tu celular para tener tu tarjeta siempre a mano. Si la perdés, en el mostrador te pueden sumar los sellos con tu DNI.','Tip: add this page to your phone home screen to keep your card at hand. If you lose it, the counter can add your stamps with your ID number.')+'<\/p>'\n     +'<div class=\"loy-wallet\"><button type=\"button\" class=\"wal-btn wal-apple\" id=\"loy-apple\">'+L('Agregar a Apple Wallet','Add to Apple Wallet')+'<\/button><button type=\"button\" class=\"wal-btn wal-google\" id=\"loy-google\">'+L('Guardar en Google Wallet','Save to Google Wallet')+'<\/button><\/div><div id=\"loy-walbox\" role=\"status\" hidden><\/div>'\n     +'<button type=\"button\" class=\"loy-btn loy-alt\" id=\"loy-save\">'+L('Guardar mi tarjeta (por si cambio de celular)','Save my card (in case I change phones)')+'<\/button><div id=\"loy-savebox\" hidden><\/div>'\n     +'<button type=\"button\" class=\"loy-link\" id=\"loy-out\">'+L('No soy yo / quitar tarjeta de este dispositivo','Not me / remove card from this device')+'<\/button><\/div>';\n    $('#loy-show').addEventListener('click',showCode);\n    $('#loy-save').addEventListener('click',toggleSave);\n    $('#loy-apple').addEventListener('click',function(){walletGo('apple');});\n    $('#loy-google').addEventListener('click',function(){walletGo('google');});\n    $('#loy-out').addEventListener('click',function(){try{localStorage.removeItem('rave.card');}catch(e){} renderCard(); renderCoupons();});\n    renderPlans(c);\n  }\n  /* --- Apple Wallet / Google Wallet: en la demo es una simulación rotulada; sin cuenta del comercio, se explica qué falta --- */\n  function walletGo(kind){\n    var box=$('#loy-walbox'); if(!box) return; var r=null; try{ r=API.wallet?API.wallet(cardId(),kind):null; }catch(e){}\n    var nm=kind==='apple'?'Apple Wallet':'Google Wallet';\n    if(r&&r.mode==='demo'&&r.html){ box.innerHTML=r.html+'<button type=\"button\" class=\"loy-link\" id=\"wal-close\">'+L('Cerrar','Close')+'<\/button>'; box.hidden=false; var x=$('#wal-close'); if(x) x.addEventListener('click',function(){box.hidden=true;}); return; }\n    if(r&&r.mode==='live'&&r.url&&/^https:\\/\\//.test(r.url)){ window.open(r.url,'_blank','noopener'); return; }\n    box.innerHTML='<p class=\"loy-tip\">'+L(nm+' todavía no está activado en este comercio. Mientras tanto guardá tu tarjeta con «Guardar mi tarjeta» (enlace e imagen con QR) o agregá esta página a la pantalla de inicio.',nm+' is not enabled by this shop yet. Meanwhile save your card with “Save my card” (link and QR image) or add this page to your home screen.')+'<\/p>'; box.hidden=false;\n  }\n  /* --- guardar la tarjeta fuera del navegador: enlace, compartir e imagen con QR --- */\n  function toggleSave(){\n    var box=$('#loy-savebox'); if(!box) return; if(!box.hidden){box.hidden=true;return;}\n    var id=cardId(), p=null; try{p=API.cardPortable?API.cardPortable(id):null;}catch(e){}\n    if(!p){ box.innerHTML='<p class=\"loy-tip\">'+L('No pudimos preparar tu tarjeta para guardarla. Probá de nuevo en unos segundos.','We could not prepare your card to be saved. Please try again in a few seconds.')+'<\/p>'; box.hidden=false; return; }\n    box.innerHTML='<p class=\"loy-tip\">'+L('Este enlace es tu tarjeta personal: si cambiás de celular o se borran los datos del navegador, abrilo (o escaneá el QR de la imagen) y tu tarjeta vuelve. No lo compartas con nadie.','This link is your personal card: if you change phones or the browser data is cleared, open it (or scan the QR in the image) and your card comes back. Do not share it.')+'<\/p>'\n      +'<button type=\"button\" class=\"loy-btn\" id=\"sv-img\">'+L('Descargar imagen con QR','Download image with QR')+'<\/button>'\n      +'<button type=\"button\" class=\"loy-btn loy-alt\" id=\"sv-copy\">'+L('Copiar enlace de mi tarjeta','Copy my card link')+'<\/button>'\n      +(navigator.share?'<button type=\"button\" class=\"loy-btn loy-alt\" id=\"sv-share\">'+L('Compartir conmigo (WhatsApp, correo, notas)','Send to myself (WhatsApp, email, notes)')+'<\/button>':'')\n      +'<div class=\"loy-tip\" id=\"sv-msg\" role=\"status\"><\/div>';\n    box.hidden=false;\n    function say(t){var m=$('#sv-msg'); if(m) m.textContent=t;}\n    $('#sv-copy').addEventListener('click',function(){\n      var done=function(){say(L('Enlace copiado. Pegalo en tus notas o mandátelo por WhatsApp.','Link copied. Paste it in your notes or send it to yourself on WhatsApp.'));};\n      try{ navigator.clipboard.writeText(p.link).then(done,function(){prompt(L('Copiá el enlace:','Copy the link:'),p.link);}); }catch(e){ prompt(L('Copiá el enlace:','Copy the link:'),p.link); }\n    });\n    var sh=$('#sv-share'); if(sh) sh.addEventListener('click',function(){ navigator.share({title:L('Mi tarjeta del Club','My Club card'),text:L('Mi tarjeta del Club (personal, no la compartas):','My Club card (personal, do not share):'),url:p.link}).catch(function(){}); });\n    $('#sv-img').addEventListener('click',function(){ drawCardPng(p,id,function(ok){ say(ok?L('Listo: la imagen se descargó. Guardala en tu galería.','Done: the image was downloaded. Keep it in your gallery.'):L('No se pudo generar la imagen en este navegador. Usá «Copiar enlace».','The image could not be created in this browser. Use “Copy link”.')); }); });\n  }\n  function drawCardPng(p,id,cb){\n    try{\n      var c=document.createElement('canvas'); c.width=720; c.height=460; var g=c.getContext('2d');\n      g.fillStyle='#242220'; g.fillRect(0,0,720,460); g.strokeStyle='#c9963e'; g.lineWidth=6; g.strokeRect(12,12,696,436);\n      g.fillStyle='#c9963e'; g.font='700 30px Poppins,Arial,sans-serif'; var t=''; try{t=API.site().title||'';}catch(e){} g.fillText(String(t||'Club').slice(0,28),40,70);\n      g.fillStyle='#fff'; g.font='600 26px Poppins,Arial,sans-serif'; g.fillText(L('Tarjeta del Club','Club card'),40,112);\n      g.font='700 34px Poppins,Arial,sans-serif'; g.fillText(String(p.name||'').slice(0,18),40,190);\n      g.fillStyle='#d9cbb0'; g.font='500 18px Poppins,Arial,sans-serif';\n      L('Escaneá el QR con la cámara','Scan the QR with your camera').split('\\n').forEach(function(l,i){g.fillText(l,40,250+i*26);});\n      g.fillText(L('para recuperar tu tarjeta en un celular nuevo.','to get your card back on a new phone.'),40,276);\n      g.fillStyle='#e8c98d'; g.font='500 15px Poppins,Arial,sans-serif'; g.fillText(L('Personal: no la compartas con nadie.','Personal: do not share it.'),40,420);\n      var img=new Image(); var url=URL.createObjectURL(new Blob([p.qr],{type:'image/svg+xml'}));\n      img.onload=function(){ g.fillStyle='#fff'; g.fillRect(400,60,290,290); g.drawImage(img,405,65,280,280); URL.revokeObjectURL(url);\n        c.toBlob(function(b){ if(!b) return cb(false); var a=document.createElement('a'); a.href=URL.createObjectURL(b); a.download='mi-tarjeta-del-club.png'; document.body.appendChild(a); a.click(); setTimeout(function(){URL.revokeObjectURL(a.href); a.remove();},1500); cb(true); },'image/png'); };\n      img.onerror=function(){ cb(false); }; img.src=url;\n    }catch(e){ cb(false); }\n  }\n  function showCode(){\n    var id=cardId(), box=$('#loy-codebox'); if(!id||!box) return;\n    function draw(){\n      var k=API.cardCode(id); if(!k){box.innerHTML=''; stopTick(); return;}\n      box.innerHTML='<div class=\"loy-code\">'+k.qr+'<div class=\"lc-n\">'+(k.pending?esc(k.otp):esc(k.socio)+' · '+esc(k.otp))+'<\/div>'+(k.pending?'<div class=\"lc-s\">'+L('Tarjeta todavía no activada: mostrá igual este QR en el mostrador.','Card not activated yet: show this QR at the counter anyway.')+'<\/div>':'')+'<div class=\"lc-s\">'+L('Mostralo en el mostrador · vence en ','Show it at the counter · expires in ')+'<b id=\"lc-t\">'+k.secs+'<\/b> s · '+L('un sello por día','one stamp per day')+'<\/div><\/div>';\n    }\n    draw(); stopTick();\n    tick=setInterval(function(){\n      var t=$('#lc-t'); if(!t){stopTick();return;}\n      var s=+t.textContent-1; if(s<=0){draw();} else t.textContent=s;\n      if(!$('#loy-card')||$('#loy-card').hidden) stopTick();\n    },1000);\n  }\n  function renderPlans(c){\n    var box=$('#plans-box'), list=$('#plans-list'); if(!box) return;\n    var ps=API.plans(); box.hidden=!ps.length;\n    list.innerHTML=ps.map(function(p){return '<div class=\"pl\"><b>'+esc(p.name)+'<\/b> · '+money(p.price)+' / '+esc(p.period)+'<br>'+esc(p.desc)+'<\/div>';}).join('');\n  }\n\n  /* --- TIENDA CON ENVÍOS: entrega, costo por provincia y datos de envío en el carrito (sólo si el comercio la activó) --- */\n  (function(){\n    var panel=$('#cart-panel'), totalRow=panel&&panel.querySelector('.cp-total-row'); if(!panel||!totalRow) return;\n    var box=document.createElement('div'); box.id='ship-box'; box.hidden=true; panel.insertBefore(box,totalRow);\n    var S0={method:'',prov:'',f:{}};\n    function cfg(){ try{ var s=API.site(); return (s&&s.ship&&s.ship.mode==='tienda')?s.ship:null; }catch(e){ return null; } }\n    function sub(){ var t=$('#cp-total-val'); if(!t) return 0; return parseInt(String(t.textContent).replace(/[^\\d,]/g,'').split(',')[0]||'0',10)||0; }\n    function hasAlc(){ var alc=window.RAVE_CATS_ALC||[], pr=[]; try{pr=API.catalog().productos||[];}catch(e){}\n      var rows=panel.querySelectorAll('.cp-item[data-pid]'); for(var i=0;i<rows.length;i++){ var id=rows[i].getAttribute('data-pid'); for(var j=0;j<pr.length;j++){ if(String(pr[j].id)===id && alc.indexOf(pr[j].cat)>=0) return true; } } return false; }\n    function options(c){ var o=[]; if(c.pickup) o.push(['pickup',L('Retiro en el local','Pick up at the shop')]); if(c.local) o.push(['local',L('Envío local','Local delivery')]); if(c.zones.length||c.rest) o.push(['nacional',L('Envío a otra provincia','Shipping to another province')]); return o; }\n    /* devuelve {fee:Number|null, eta, label, free} (null = a cotizar) */\n    function quote(c,m,prov,s){\n      if(m==='pickup') return {fee:0,eta:'',label:L('Retiro sin costo','Free pick up')};\n      if(m==='local'){ var f=c.local.fee, fr=c.local.free>0&&s>=c.local.free; return {fee:fr?0:f,eta:'',label:fr?L('Envío gratis','Free delivery'):''}; }\n      var z=null; for(var i=0;i<c.zones.length;i++){ if(c.zones[i].prov===prov) z=c.zones[i]; }\n      if(z){ var free=z.free>0&&s>=z.free; return {fee:free?0:z.fee,eta:z.eta,label:free?L('Envío gratis','Free shipping'):'',carrier:z.carrier}; }\n      if(c.rest&&prov==='__rest') return c.rest.quote?{fee:null,eta:c.rest.eta,label:L('A cotizar por WhatsApp','Quoted on WhatsApp')}:{fee:c.rest.fee,eta:c.rest.eta,label:''};\n      return null;\n    }\n    function esc2(t){ return String(t==null?'':t).replace(/[&<>\"']/g,function(ch){return({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'})[ch];}); }\n    function fld(id,lbl,ph,mx){ return '<label for=\"'+id+'\">'+lbl+'<\/label><input id=\"'+id+'\" maxlength=\"'+mx+'\" placeholder=\"'+esc2(ph||'')+'\" autocomplete=\"off\" value=\"'+esc2(S0.f[id]||'')+'\">'; }\n    function render(){\n      var c=cfg(); if(!c){ box.hidden=true; box.innerHTML=''; return; }\n      var op=options(c); if(!op.length){ box.hidden=true; return; }\n      if(!S0.method||!op.some(function(x){return x[0]===S0.method;})) S0.method=op[0][0];\n      var h='<h4 class=\"sh-h\">'+L('Entrega','Delivery')+'<\/h4><div class=\"sh-opts\" role=\"radiogroup\" aria-label=\"'+L('Forma de entrega','Delivery method')+'\">';\n      op.forEach(function(x){ h+='<label class=\"sh-opt\"><input type=\"radio\" name=\"sh-m\" value=\"'+x[0]+'\" '+(S0.method===x[0]?'checked':'')+'> '+x[1]+'<\/label>'; });\n      h+='<\/div>';\n      if(S0.method==='pickup'){ h+='<p class=\"sh-n\">'+esc2(c.pickup.place)+(c.pickup.hours?' · '+esc2(c.pickup.hours):'')+'<\/p>'; }\n      else {\n        if(S0.method==='nacional'){\n          h+='<label for=\"sh-prov\">'+L('Provincia','Province')+'<\/label><select id=\"sh-prov\"><option value=\"\">'+L('Elegí tu provincia','Choose your province')+'<\/option>';\n          c.zones.forEach(function(z){ h+='<option value=\"'+esc2(z.prov)+'\" '+(S0.prov===z.prov?'selected':'')+'>'+esc2(z.prov)+'<\/option>'; });\n          if(c.rest) h+='<option value=\"__rest\" '+(S0.prov==='__rest'?'selected':'')+'>'+L('Otra provincia (a cotizar)','Another province (quote)')+'<\/option>';\n          h+='<\/select>';\n        } else if(c.local.zones){ h+='<p class=\"sh-n\">'+L('Zonas: ','Areas: ')+esc2(c.local.zones)+'<\/p>'; }\n        h+=fld('sh-name',L('Nombre de quien recibe','Recipient name'),'',60)+fld('sh-tel',L('Teléfono de contacto','Contact phone'),'',20)+fld('sh-street',L('Calle y número','Street and number'),'',80)+fld('sh-city',L('Localidad','City'),'',60)+fld('sh-cp',L('Código postal','Postal code'),'',10)+fld('sh-obs',L('Indicaciones (piso, horario, referencias)','Notes (floor, time, landmarks)'),'',120);\n      }\n      h+='<div class=\"sh-sum\" id=\"sh-sum\" role=\"status\" aria-live=\"polite\"><\/div><div class=\"sh-err\" id=\"sh-err\" role=\"alert\" hidden><\/div>';\n      if(c.note) h+='<p class=\"sh-n\">'+esc2(c.note)+'<\/p>';\n      h+='<p class=\"sh-n\">'+L('Es una solicitud: el comercio te confirma disponibilidad, costo y plazo por WhatsApp. Tus datos de entrega sólo van en ese mensaje; este menú no los guarda.','This is a request: the shop confirms stock, cost and time on WhatsApp. Your delivery details only go in that message; this menu does not store them.')+'<\/p>';\n      box.innerHTML=h; box.hidden=false; bind(); summary();\n    }\n    function bind(){\n      box.querySelectorAll('input[name=sh-m]').forEach(function(r){ r.addEventListener('change',function(){ keep(); S0.method=r.value; render(); }); });\n      var p=$('#sh-prov'); if(p) p.addEventListener('change',function(){ keep(); S0.prov=p.value; summary(); });\n      box.querySelectorAll('input[type=text],input:not([type])').forEach(function(i){ i.addEventListener('input',function(){S0.f[i.id]=i.value;}); });\n    }\n    function keep(){ box.querySelectorAll('input[id^=sh-]').forEach(function(i){S0.f[i.id]=i.value;}); }\n    function fee(c){ return quote(c,S0.method,S0.prov,sub()); }\n    function summary(){\n      var c=cfg(), el=$('#sh-sum'); if(!c||!el) return; var s=sub(), q=fee(c), t='';\n      if(S0.method==='nacional'&&!S0.prov) t=L('Elegí la provincia para ver el costo de envío.','Choose the province to see the shipping cost.');\n      else if(!q) t='';\n      else { t='<b>'+L('Envío','Shipping')+':<\/b> '+(q.fee===null?q.label:(q.fee===0?(q.label||L('sin costo','free')):money(q.fee)))+(q.eta?' · '+esc2(q.eta):'')+(q.carrier?' · '+esc2(q.carrier):'');\n        if(q.fee!==null) t+='<br><b>'+L('Total con envío (estimado)','Total with shipping (estimate)')+':<\/b> '+money(s+q.fee); else t+='<br>'+L('El costo se suma al total cuando el comercio lo cotice.','The cost is added to the total once the shop quotes it.'); }\n      el.innerHTML=t;\n    }\n    function validate(){\n      var c=cfg(); if(!c) return ''; var s=sub();\n      if(S0.method!=='pickup'){\n        if(c.min>0&&s<c.min) return L('La compra mínima para envíos es ','The minimum purchase for delivery is ')+money(c.min)+'.';\n        if(S0.method==='nacional'&&!S0.prov) return L('Elegí la provincia de entrega.','Choose the delivery province.');\n        if(!c.alcohol&&hasAlc()) return L('Las bebidas alcohólicas se retiran en el local: sacalas del pedido o elegí «Retiro en el local».','Alcoholic drinks are pick-up only: remove them or choose “Pick up at the shop”.');\n        keep(); var f=S0.f, need=[['sh-name',L('el nombre de quien recibe','the recipient name')],['sh-tel',L('un teléfono de contacto','a contact phone')],['sh-street',L('calle y número','street and number')],['sh-city',L('la localidad','the city')]];\n        for(var i=0;i<need.length;i++){ if(String(f[need[i][0]]||'').trim().length<2) return L('Falta ','Missing ')+need[i][1]+'.'; }\n        if(S0.method==='nacional'&&!/^[A-Za-z]?\\d{4}[A-Za-z]{0,3}$/.test(String(f['sh-cp']||'').trim())) return L('Ingresá un código postal válido (4 números).','Enter a valid postal code (4 digits).');\n        if(!/^[\\d\\s+()-]{6,20}$/.test(String(f['sh-tel']||'').trim())) return L('Ingresá un teléfono válido.','Enter a valid phone number.');\n      }\n      return '';\n    }\n    var send=$('#btn-send');\n    if(send) send.addEventListener('click',function(ev){ var c=cfg(); if(!c||box.hidden) return; var m=validate(), er=$('#sh-err'); if(m){ ev.stopImmediatePropagation(); ev.preventDefault(); if(er){er.textContent=m;er.hidden=false;er.scrollIntoView&&er.scrollIntoView({block:'nearest'});} } else if(er){ er.hidden=true; } },true);\n    window.RAVE_SHIP_LINES=function(lines,total){\n      var c=cfg(); if(!c||box.hidden) return; keep(); var f=S0.f, q=fee(c); lines.push('');\n      lines.push('ENTREGA: '+({pickup:'Retiro en el local',local:'Envío local',nacional:'Envío a otra provincia'})[S0.method]);\n      if(S0.method!=='pickup'){\n        lines.push('Recibe: '+String(f['sh-name']||'').trim()+' · Tel: '+String(f['sh-tel']||'').trim());\n        lines.push('Dirección: '+String(f['sh-street']||'').trim()+', '+String(f['sh-city']||'').trim()+(S0.method==='nacional'?', '+(S0.prov==='__rest'?'(otra provincia)':S0.prov)+(String(f['sh-cp']||'').trim()?' (CP '+String(f['sh-cp']).trim()+')':''):''));\n        if(String(f['sh-obs']||'').trim()) lines.push('Indicaciones: '+String(f['sh-obs']).trim());\n        if(q){ lines.push('Envío: '+(q.fee===null?'a cotizar':(q.fee===0?'sin costo':money(q.fee)))+(q.eta?' ('+q.eta+')':'')); if(q.fee!==null) lines.push('Total con envío estimado: '+money(total+q.fee)); }\n      }\n    };\n    var tv=$('#cp-total-val'); if(tv&&window.MutationObserver) new MutationObserver(function(){ summary(); }).observe(tv,{childList:true,characterData:true,subtree:true});\n    var cb=$('#cart-bar'); if(cb) cb.addEventListener('click',function(){ setTimeout(render,0); });\n    window.RAVE_SHIP_REFRESH=render; render();\n  })();\n  window.RAVE_CARD_REFRESH=function(){renderCard();renderCoupons();};\n  var rb=$('#loy-recover');\n  if(rb) rb.addEventListener('click',function(){\n    var id=API.cardLogin($('#loy-wa').value,$('#loy-bd').value), er=$('#loy-err');\n    if(!id){er.style.display='block';return;} er.style.display='none';\n    try{localStorage.setItem('rave.card',id);}catch(e){}\n    $('#loy-wa').value='';$('#loy-bd').value=''; renderCard(); renderCoupons();\n  });\n\n  /* --- información legal (los textos se editan en Administración → Legal y cumplimiento) --- */\n  function renderLegal(){\n    var list=$('#legal-list'); if(!list) return;\n    var items=API.legal(); var note='<p class=\"legal-lang-note\">'+L('Texto vigente en español.','The text below is the legally binding Spanish version.')+'<\/p>';\n    items.forEach(function(x){ if(x.id==='privacidad'){ var b=$('#legal-rave .legal-body'); if(b) b.innerHTML=note+x.html; } });\n    list.innerHTML=items.filter(function(x){return x.id!=='privacidad';}).map(function(x){return '<details class=\"legal-details\"><summary>'+esc(L(x.title,x.titleEn||x.title))+'<\/summary><div class=\"legal-body\">'+note+x.html+'<\/div><\/details>';}).join('');\n  }\n  var ab=$('#arrep-btn');\n  if(ab) ab.addEventListener('click',function(){\n    var t='Botón de arrepentimiento: quiero revocar mi compra. Pedido/fecha: ____ Nombre: ____ (dentro de los 10 días corridos).';\n    window.open('https://wa.me/'+(window.RAVE_WA||'')+'?text='+encodeURIComponent(t),'_blank');\n    try{API.logArrep();}catch(e){}\n  });\n\n  /* al cambiar de idioma se vuelven a dibujar las partes dinámicas */\n  var lastLang=L('es','en');\n  setInterval(function(){var l=L('es','en'); if(l!==lastLang){lastLang=l; renderCard(); renderCoupons(); renderLegal();}},500);\n  renderCoupons(); renderCard(); renderLegal();\n  /* si el panel cambia datos (cupones, sellos) el menú se redibuja */\n  window.RAVE_PUB_REFRESH=function(){renderCoupons();renderCard();renderLegal();try{if(window.RAVE_SHIP_REFRESH)window.RAVE_SHIP_REFRESH();}catch(e){}};\n})();\n\n<\/script>\n<\/body><\/html>";
